Q: Select data from multiple date columns with and conditions in Code Igniter A: <pre><code>$this-&gt;db-&gt;select('*');
   $this-&gt;db-&gt;from('BaseTbl');
   $this-&gt;db-&gt;where('date(remarkDate) &lt;=',date('Y-m-d') );
   $this-&gt;db-&gt;where('date(createdDate) !=',date('Y-m-d') );
   $query = $this-&gt;db-&gt;get();
   $result = $query-&gt;num_rows();      
   return $result;
</code></pre>

<p>Hope this will work</p>
